import { config } from "dotenv";
import { serve } from "@hono/node-server";
import { Hono } from "hono";
import { cors } from "hono/cors";
import { authRouter } from "@/features/auth/routes";

config();

const app = new Hono();

app.use(
  "*",
  cors({
    origin: String(process.env.CORS_ORIGIN ?? "http://localhost:3000").split(","),
    credentials: true,
  })
);

app.route("/auth", authRouter);

const port = Number(process.env.PORT ?? 4000);
serve({ fetch: app.fetch, port });
console.log(`Server running on http://localhost:${port}`);

import { Hono } from "hono";
import { validate } from "@/features/auth/middlewares/validate";
import { signupSchema } from "@/features/auth/validation/signup";
import { loginSchema } from "@/features/auth/validation/login";
import { signupHandler } from "@/features/auth/controllers/signupHandler";
import { loginHandler } from "@/features/auth/controllers/loginHandler";
import { logoutHandler } from "@/features/auth/controllers/logoutHandler";
import { meHandler } from "@/features/auth/controllers/meHandler";

const authRouter = new Hono();

authRouter.post("/signup", validate(signupSchema), signupHandler);
authRouter.post("/login", validate(loginSchema), loginHandler);
authRouter.get("/logout", logoutHandler);
authRouter.get("/me", meHandler);

export { authRouter };

import type { Context, Next } from "hono";
import type { ZodSchema } from "zod";

export const validate =
  (schema: ZodSchema) =>
  async (c: Context, next: Next) => {
    const body = await c.req.json().catch(() => ({}));
    const result = schema.safeParse(body);

    if (!result.success) {
      return c.json(
        {
          message: "Validation failed",
          errors: result.error.flatten().fieldErrors,
        },
        400
      );
    }

    c.set("validated", result.data);
    return next();
  };

import type { Context } from "hono";
import argon2 from "argon2";
import { prisma } from "@/config";

export const signupHandler = async (c: Context) => {
  const userDetails = c.get("validated");

  const hashedPassword = await argon2.hash(userDetails.password);

  const user = await prisma.user.create({
    data: {
      name: userDetails.name,
      email: userDetails.email,
      password: hashedPassword,
    },
    select: { id: true, email: true, name: true },
  });

  return c.json(user, 200);
};

import type { Context } from "hono";
import argon2 from "argon2";
import { prisma } from "@/config";

export const loginHandler = async (c: Context) => {
  const credentials = c.get("validated");

  const user = await prisma.user.findUnique({
    where: { email: credentials.email },
    select: { id: true, name: true, email: true, password: true },
  });

  if (!user) {
    return c.json({ message: "User not found" }, 404);
  }

  const valid = await argon2.verify(user.password, credentials.password);
  if (!valid) {
    return c.json({ message: "Invalid credentials" }, 401);
  }

  return c.json({ id: user.id, name: user.name, email: user.email }, 200);
};

import type { Context } from "hono";

export const logoutHandler = async (c: Context) => {
  return c.json({ message: "User logged out successfully" }, 200);
};

import type { Context } from "hono";
import { prisma } from "@/config";

export const meHandler = async (c: Context) => {
  const userId = c.req.query("userId");

  if (!userId) {
    return c.json({ message: "Not authenticated" }, 401);
  }

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { id: true, email: true, name: true },
  });

  return c.json(user, 200);
};

import { z } from "zod";

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

export type LoginInput = z.infer<typeof loginSchema>;

import { z } from "zod";

export const signupSchema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  password: z.string().min(8),
});

export type SignupInput = z.infer<typeof signupSchema>;
